const fixture = readFixedExistingOpsGitFixture();
const { revision } = fixture;
const sourcePath='packages/brain/src/lib/existing-ops-source.js';
const paths=[...new Set([...fixture.paths,...Object.keys(candidate.blobs)])];
const read=path=>candidate.blobs[path]??fixture.read(path);
async function build({marker=1,patch={},missing}={}){
 const result=await buildExistingOpsSources({scope:'cecelia-factory',repo:'perfectuser21/cecelia',revision,paths,readSource:async path=>{
  if(path===missing)throw Error('missing fixed input');let text=patch[path]??read(path);
  if(path===sourcePath){text=text.replace(/^export const EXISTING_OPS_AUTO_VERSION_SELECTOR_SCHEMA = .*;\n/m,'');if(marker!==null)text+=`\nexport const EXISTING_OPS_AUTO_VERSION_SELECTOR_SCHEMA = ${marker};\n`;}
  return text;
 }});return result.consumers.find(c=>c.workflow_key==='factory_f3_ops');
}
it('已知历史Git fixture 的nightly测试读取YAML并执行guard/apply；不证明当前候选或生产发布',async()=>{
 for(const[path,text]of Object.entries(candidate.blobs))expect(createHash('sha256').update(text).digest('hex')).toBe(candidate.blob_sha256[path]);
 const result=await build();expect(result.status,JSON.stringify(result.gaps)).toBe('verified');
 for(const path of Object.keys(candidate.blobs))expect(result.bindings).toContainEqual(expect.objectContaining({path,revision,digest:`sha256:${candidate.blob_sha256[path]}`}));
 expect(result.input_relations).toContainEqual(expect.objectContaining({consumer_path:'packages/brain/vitest.config.js',input_path:'packages/brain/src/__tests__/auto-version-decision.test.js',kind:'literal_vitest_verification_selector'}));
});
it.each(Object.keys(candidate.blobs))('丢失实际自动版本测试来源%s拒绝无部分绑定',async missing=>{
 const result=await build({missing});expect(result.status).toBe('unknown');expect(result.bindings).toEqual([]);
});
it.each(Object.keys(candidate.blobs))('未知自动版本测试来源字节%s拒绝',async path=>{
 const result=await build({patch:{[path]:read(path)+'\n// unreviewed\n'}});expect(result.status).toBe('unknown');expect(result.bindings).toEqual([]);
});
it.each([null,0])('旧selector%s保持旧绑定且不认领新版本来源',async marker=>{
 const result=await build({marker});expect(result.status,JSON.stringify(result.gaps)).toBe('verified');
 expect(result.bindings.some(b=>b.path==='packages/brain/scripts/auto-version-decision.mjs')).toBe(false);
});
it('未知selector拒绝且无部分绑定',async()=>{const result=await build({marker:2});expect(result.status).toBe('unknown');expect(result.bindings).toEqual([]);});
it('实际nightly配置排除该测试则不能认领',async()=>{
 const path='packages/brain/vitest.config.js';const text=read(path).replace('exclude: [',"exclude: ['src/__tests__/auto-version-decision.test.js',");expect(text).not.toBe(read(path));
 const result=await build({patch:{[path]:text}});expect(result.status).toBe('unknown');expect(result.bindings).toEqual([]);
});

